function formBox(type){let b=$(type+"FormBox");if(type==="leave")b.innerHTML=`<div class="module-form"><label>Staff<select id="lf_staff">${staffOptions()}</select></label><label>From<input id="lf_from" type="date" value="${today()}"></label><label>To<input id="lf_to" type="date" value="${today()}"></label><label>Type<select id="lf_type"><option>Casual Leave</option><option>Sick Leave</option><option>Earned Leave</option><option>Other</option></select></label><label class="wide">Reason<input id="lf_reason"></label></div><button class="module-btn primary form-save-leave">Save Leave</button>`;if(type==="advance")b.innerHTML=`<div class="module-form"><label>Staff<select id="ad_staff">${staffOptions()}</select></label><label>Date<input id="ad_date" type="date" value="${today()}"></label><label>Amount<input id="ad_amount" type="number"></label><label class="wide">Reason<input id="ad_reason"></label></div><button class="module-btn primary form-save-advance">Save Advance</button>`;if(type==="promotion")b.innerHTML=`<div class="module-form"><label>Staff<select id="pr_staff">${staffOptions()}</select></label><label>Effective Date<input id="pr_date" type="date" value="${today()}"></label><label>New Designation<input id="pr_role"></label><label>New Salary<input id="pr_salary" type="number"></label><label class="wide">Reason<input id="pr_reason"></label></div><button class="module-btn primary form-save-promotion">Save Promotion</button>`;if(type==="accounts")b.innerHTML=`<div class="module-form"><label>Date<input id="ac_date" type="date" value="${today()}"></label><label>Amount<input id="ac_amount" type="number"></label><label>Payment Method<select id="ac_method"><option>Cash</option><option>Bank</option><option>UPI</option><option>Other</option></select></label><label>Category / Source<input id="ac_category"></label><label class="wide">Description / Party<input id="ac_desc"></label><label>Reference<input id="ac_ref"></label></div><button class="module-btn primary form-save-account">Save</button>`;b.hidden=false}
async function saveForm(type){let r;if(type==="leave")r=await sb.from("leaves").insert({staff_id:$("lf_staff").value,from_date:$("lf_from").value,to_date:$("lf_to").value,leave_type:$("lf_type").value,reason:$("lf_reason").value});if(type==="advance")r=await sb.from("staff_advances").insert({staff_id:$("ad_staff").value,advance_date:$("ad_date").value,amount:Number($("ad_amount").value||0),reason:$("ad_reason").value});if(type==="promotion"){let s=company.staff.find(x=>x.id===$("pr_staff").value);r=await sb.from("promotions").insert({staff_id:s.id,effective_date:$("pr_date").value,old_designation:s.designation,new_designation:$("pr_role").value,old_salary:s.salary,new_salary:Number($("pr_salary").value||0),reason:$("pr_reason").value});if(!r.error)await sb.from("staff").update({designation:$("pr_role").value,salary:Number($("pr_salary").value||0)}).eq("id",s.id)}if(type==="accounts"){let isExpense=$("accountsFormBox").dataset.mode==="expense",isIncome=$("accountsFormBox").dataset.mode==="income";let base={expense_date:$("ac_date").value,category:$("ac_category").value,description:$("ac_desc").value,amount:Number($("ac_amount").value||0),payment_method:$("ac_method").value,reference:$("ac_ref").value};if(isExpense)r=await sb.from("expenses").insert(base);else if(isIncome)r=await sb.from("income").insert({income_date:base.expense_date,source:base.category,description:base.description,amount:base.amount,payment_method:base.payment_method,reference:base.reference});else r=await sb.from("payments").insert({payment_date:base.expense_date,payment_type:"other",party_name:base.description,amount:base.amount,direction:"out",method:base.payment_method,reference:base.reference})}if(r?.error)msg(r.error.message);else{await loadCompany();msg("Saved successfully.",true)}}
function renderUsers(){$("usersTable").innerHTML=company.users.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.email)}</td><td>${esc(u.role)}</td><td>${u.active?"Yes":"No"}</td><td><small>${esc(u.auth_user_id||"")}</small></td><td><button class="module-btn danger delete-user" data-id="${u.id}">Delete</button></td></tr>`).join("")||`<tr><td colspan="6">No role records.</td></tr>`}
function letterTypeLabel(t){return ({offer:"Offer Letter",joining:"Joining Letter",warning:"Warning Letter",termination:"Termination Letter"})[t]||t||""}
function selectedLetterStaff(){
  const id=String(selectedStaffId||$("letterStaff")?.value||"");
  if(!id)return null;
  return company.staff.find(x=>String(x.id)===id)||null;
}
function performancePolicyFor(s){
  const d=String(s?.designation||"").toLowerCase().replace(/[._-]/g," ").replace(/\s+/g," ").trim();
  if(d.includes("district coordinator")||d==="dc"||d.includes("district co ordinator"))
    return "District Coordinator: performance-linked salary/payment components, where applicable, are assessed against verified district/TL team performance, including target achievement, verified output, attendance, reporting accuracy and conduct. Any fixed salary remains governed by the Offer/Joining Letter and applicable law.";
  if(d.includes("team leader")||d==="tl"||d.includes("teamlead")||d.includes("team lead"))
    return "Team Leader: performance-linked salary/payment components, where applicable, are assessed against verified team performance, including team target achievement, verified output, attendance, reporting accuracy and conduct. Any fixed salary remains governed by the Offer/Joining Letter and applicable law.";
  return "Field Staff: verified individual card/output performance is mapped as follows where the project performance component applies — 850+ verified cards = 100%; 700–849 = 75%; 550–699 = 50%. Below 550, the applicable project policy/Offer Letter governs. Attendance, reporting accuracy, conduct and verification requirements also apply.";
}
function warningBasisFor(reason,s){
  const r=String(reason||"");
  if(r==="Misconduct / Behaviour") return "This warning concerns verified misconduct / behaviour in the course of assigned duties. The employee is required to maintain professional conduct, respectful communication and compliance with Company instructions. Any specific incident or factual record should be stated in the Details / Remarks field.";
  if(r==="Attendance / Unauthorised Absence") return "This warning concerns attendance / unauthorised absence. The employee is required to report as scheduled, follow the approved leave process and maintain accurate attendance records. Any specific dates or attendance facts should be stated in the Details / Remarks field.";
  if(r==="Communication / Reporting Failure") return "This warning concerns communication / reporting requirements. The employee is required to follow the reporting chain, provide timely and accurate updates, and comply with assigned communication procedures. Any specific facts should be stated in the Details / Remarks field.";
  if(r==="Other Operational Non-Compliance") return "This warning concerns a verified operational / procedural non-compliance. The employee is required to follow the applicable project instructions, Company procedures and assigned responsibilities. Any specific facts should be stated in the Details / Remarks field.";
  if(r==="Performance / Target Non-Compliance") return performancePolicyFor(s);
  return "This warning concerns the selected verified area of concern. The employee is required to follow applicable Company instructions, role requirements and project procedures. Any specific facts should be stated in the Details / Remarks field.";
}

function renderLetters(){
  const previous=selectedStaffId||$("letterStaff")?.value||"";
  let s=$("letterStaff");
  if(s)s.innerHTML=staffOptions(previous);
  if(s && ![...s.options].some(o=>String(o.value)===String(previous)))s.value="";
  if($("letterDate")&&!$("letterDate").value)$("letterDate").value=today();
  if($("terminationDate")&&!$("terminationDate").value)$("terminationDate").value=today();
  updateLetterTypeUI();
  renderLetterHistory();
}
function defaultLetterSubject(type){
  return type==="warning"?"Formal Written Warning":type==="termination"?"Letter of Employment Termination":type==="offer"?"Job Offer Letter":"Joining Letter";
}
function updateLetterTypeUI(){
  const t=$("letterType")?.value||"offer";
  if($("warningFields"))$("warningFields").hidden=t!=="warning";
  if($("terminationFields"))$("terminationFields").hidden=t!=="termination";
  const s=selectedLetterStaff();
  if($("performancePolicyBox"))$("performancePolicyBox").innerHTML=s?`<b>Performance / Salary Basis:</b> ${esc(performancePolicyFor(s))}`:"Select a staff member to view the applicable designation-based performance basis.";
  if($("letterSubject")){
    const oldDefaults=["Job Offer Letter","Joining Letter","Formal Written Warning","Letter of Employment Termination"];
    if(!String($("letterSubject").value||"").trim() || oldDefaults.includes($("letterSubject").value))$("letterSubject").value=defaultLetterSubject(t);
  }
  if($("letterNumber") && s && (!String($("letterNumber").value||"").trim() || $("letterNumber").dataset.auto==="1")){
    $("letterNumber").value=autoLetterNumber(t,s,$("letterDate")?.value||today());
    $("letterNumber").dataset.auto="1";
  }
}
function autoLetterNumber(type,s,date){
  const prefix=type==="warning"?"WARN":type==="termination"?"TERM":type.toUpperCase();
  const code=String(s?.employee_code||s?.id||"").replace(/[^A-Za-z0-9]/g,"").slice(-6)||"001";
  return `SS/HR/${prefix}/${String(date||today()).slice(0,4)}/${code}`;
}
