function offerGenerationDate(){
  const d=new Date();
  return String(d.getDate()).padStart(2,"0")+"/"+String(d.getMonth()+1).padStart(2,"0")+"/"+d.getFullYear();
}
function termsConditionsPages(s,p){
  const date=offerGenerationDate();
  return TC_PDF_PAGES.map((src,i)=>{
    const isLast=i===TC_PDF_PAGES.length-1;
    return `<section class="letter-page tc-image-page"><div class="tc-pdf-wrap"><img class="tc-pdf-image" src="${src}" alt="Terms & Conditions Page ${i+1}"></div>${isLast?`<div class="tc-dynamic-date" aria-label="Generated date">Date: ${esc(date)}</div>`:""}</section>`;
  }).join("");
}

function letterHtml(){
  let s=selectedLetterStaff(); if(!s)return"";
  let p=company.profile||{},type=$("letterType").value,date=type==="offer"?today():($("letterDate").value||today()),subject=$("letterSubject").value||({offer:"Job Offer Letter",joining:"Joining Letter",warning:"Formal Written Warning",termination:"Letter of Employment Termination"}[type]||"Employee Letter"),num=$("letterNumber").value||autoLetterNumber(type,s,date),employeeAddress=staffAddress(s),logo=p.logo_url||"logo.png";
  const companyName=p.company_name||"SS ENTERPRISES", address=p.address||"Donar Road, Darbhanga", phone=p.phone||"", email=p.email||"";
  const signature=p.signature_url?`<img src="${esc(p.signature_url)}" class="authorized-sign-img"><br>`:"", stamp=p.stamp_url?`<img src="${esc(p.stamp_url)}" class="stamp-img"><br>`:"";
  const commonHead=`<div class="letter-head"><img src="${esc(logo)}" onerror="this.src='logo.png'"><div><h2>${esc(companyName)}</h2><div>${esc(address)}</div><div>${esc(phone)} ${esc(email)}</div><small>AAPKI SEVA MEIN SADA SAMARPIT</small></div></div><div class="letter-meta"><b>Ref. No: ${esc(num)}</b><b>Date: ${esc(date)}</b></div>`;
  const commonTo=`<div class="letter-to"><b>To,</b><br>${esc(s.full_name)}<br>Employee Code: ${esc(s.employee_code||"—")}<br>Designation: ${esc(s.designation||"Staff")}<br>Address: ${esc(employeeAddress||"—")}</div>`;
  const sign=`<div class="letter-sign three-sign"><div class="sign-box employee-sign">${s.employee_signature_url?`<img src="${esc(s.employee_signature_url)}" class="employee-sign-img"><br>`:""}<div class="sign-line"></div><b>Employee Signature</b><small>${esc(s.full_name)}</small></div><div class="sign-box">${stamp}<b>Company Stamp / Mohar</b></div><div class="sign-box">${signature}<b>Authorised Signatory</b></div></div>`;
  let body="";
  if(type==="warning"){
    const level=$("warningLevel")?.value||"First Warning", reason=$("warningReason")?.value||"Performance / Target Non-Compliance", days=Math.max(1,Number($("warningDays")?.value||7)), details=($("warningDetails")?.value||"").trim();
    body=`${commonHead}${commonTo}<h2 class="letter-subject">${esc(subject)}</h2><p>Dear <b>${esc(s.full_name)}</b>,</p><p>This letter is issued as a <b>${esc(level)}</b> regarding the following verified area of concern in your assigned role at ${esc(companyName)}.</p><div class="letter-detail-box"><p><b>Concern / Reason:</b> ${esc(reason)}</p><p><b>Designation:</b> ${esc(s.designation||"Staff")}</p><p><b>Applicable Basis:</b> ${esc(warningBasisFor(reason,s))}</p>${details?`<p><b>Details / Remarks:</b> ${esc(details)}</p>`:""}</div><p>You are required to immediately correct the identified issue, follow the reporting and operational instructions applicable to your role, and demonstrate sustained improvement. You are being given an improvement period of <b>${days} day(s)</b> from the date of this letter, subject to the applicable employment terms and project policy.</p><p>Failure to demonstrate satisfactory improvement may result in further disciplinary action, up to and including discontinuation of employment, where permitted by the applicable employment terms and law. This warning does not waive any rights or obligations of either party.</p>${sign}<div class="letter-footer">${esc(companyName)} | Corporate Office: ${esc(address)} | Contact: ${esc(phone)} | Email: ${esc(email)}</div>`;
  } else if(type==="termination"){
    const effective=$("terminationDate")?.value||date, reason=$("terminationReason")?.value||"Performance / Target Non-Compliance", details=($("terminationDetails")?.value||"").trim();
    body=`${commonHead}${commonTo}<h2 class="letter-subject">${esc(subject)}</h2><p>Dear <b>${esc(s.full_name)}</b>,</p><p>This letter serves as formal notification regarding the discontinuation of your employment with <b>${esc(companyName)}</b>, effective from <b>${esc(effective)}</b>, subject to the applicable employment terms, project requirements and law.</p><div class="letter-detail-box"><p><b>Reason / Basis:</b> ${esc(reason)}</p><p><b>Designation:</b> ${esc(s.designation||"Staff")}</p><p><b>Performance / Role Basis:</b> ${esc(performancePolicyFor(s))}</p>${details?`<p><b>Details / Remarks:</b> ${esc(details)}</p>`:""}</div><h3>Asset Return & Company Property</h3><p>You are required to return all Company records, customer/beneficiary information, login credentials, documents, identity card, field materials, devices and other Company property entrusted to you, as applicable.</p><h3>Final Settlement</h3><p>Final payroll settlement, approved adjustments, recoveries and applicable statutory deductions, if any, will be processed after verification of attendance, work records, outstanding dues and return of Company property, subject to applicable law and the employment terms.</p>${sign}<div class="letter-footer">${esc(companyName)} | Corporate Office: ${esc(address)} | Contact: ${esc(phone)} | Email: ${esc(email)}</div>`;
  } else {
    const offer=type==="offer", basic=Number(s.basic_salary||0),ta=Number(s.ta_travel||0),da=Number(s.da_daily||0),rent=Number(s.rent_allowance||0),other=Number(s.other_allowance||0);let b=basic,t=ta,d=da,r=rent,o=other;if(b+t+d+r+o<=0&&Number(s.salary||0)>0)b=Number(s.salary);let gross=b+t+d+r+o,annual=gross*12;
    body=`${commonHead}${commonTo}<h2 class="letter-subject">${esc(subject)}</h2><p>Dear <b>${esc(s.full_name)}</b>,</p><p>${offer?`With reference to your recent interview and discussions, we are pleased to inform you that you have been selected for employment with <b>${esc(companyName)}</b> for the position of <b>${esc(s.designation)}</b>.`:`This is to confirm that <b>${esc(s.full_name)}</b> has joined <b>${esc(companyName)}</b> as <b>${esc(s.designation)}</b>. We welcome you and wish you success in your responsibilities.`}</p><div class="letter-detail-box"><p><b>Designation:</b> ${esc(s.designation||"Staff")}</p><p><b>Department:</b> ${esc(s.department||"—")}</p><p><b>Total Monthly Gross:</b> ${money(gross)} /-</p><p><b>Annual Gross:</b> ${money(annual)} /-</p><p><b>Probation:</b> 6 Months, unless otherwise specified in writing</p><p><b>Joining Date:</b> ${esc(s.joining_date||"On or before mutually agreed date")}</p></div><div class="letter-note"><b>Performance / Salary Basis:</b> ${esc(performancePolicyFor(s))}</div><p>The applicable duties, attendance, conduct, payroll, performance and project-specific conditions shall be governed by the Offer/Joining Letter, Company Terms & Conditions and applicable law.</p><p>Please sign and retain the duplicate copy of this letter as a token of acceptance.</p>${sign}<div class="letter-footer">${esc(companyName)} | Corporate Office: ${esc(address)} | Contact: ${esc(phone)} | Email: ${esc(email)}</div><section class="letter-page salary-page"><div class="letter-watermark">SS ENTERPRISES</div>${commonHead}<h2 class="letter-subject">Salary Component</h2><table class="salary-breakup salary-breakup-final"><thead><tr><th>Salary Component</th><th>Monthly Amount</th><th>Annual Amount</th></tr></thead><tbody><tr><td>Basic Salary</td><td>${money(b)} /-</td><td>${money(b*12)} /-</td></tr><tr><td>HRA – House Rent Allowance</td><td>${money(r)} /-</td><td>${money(r*12)} /-</td></tr><tr><td>TA / Travel Allowance</td><td>${money(t)} /-</td><td>${money(t*12)} /-</td></tr><tr><td>DA / Daily Allowance</td><td>${money(d)} /-</td><td>${money(d*12)} /-</td></tr><tr><td>Other Allowance</td><td>${money(o)} /-</td><td>${money(o*12)} /-</td></tr><tr class="salary-total"><th>Total Monthly Gross Salary</th><th>${money(gross)} /-</th><th>${money(annual)} /-</th></tr></tbody></table><div class="letter-note"><b>Performance / Salary Basis:</b> ${esc(performancePolicyFor(s))}</div><div class="letter-sign two-sign"><div class="sign-box">${stamp}<b>Company Stamp / Mohar</b></div><div class="sign-box">${signature}<b>Authorised Signatory</b></div></div><div class="letter-footer">${esc(companyName)} | Corporate Office: ${esc(address)} | Contact: ${esc(phone)} | Email: ${esc(email)}</div></section>`;
  }
  const attachment=(type==="offer")?termsConditionsPages(s,p):"";
  // Keep the Offer Letter and Salary Page as separate A4 pages.
  // The Salary Page is intentionally NOT removed; only its nested page wrapper
  // is split out so html2pdf does not create spill/blank pages.
  let mainBody=body, extraPages="";
  if(type==="offer"){
    const marker='<section class="letter-page salary-page">';
    const cut=body.indexOf(marker);
    if(cut>=0){
      mainBody=body.slice(0,cut);
      extraPages=body.slice(cut);
    }
  }
  return `<div class="letter-document"><section class="letter-page"><div class="letter-watermark">SS ENTERPRISES</div>${mainBody}</section>${extraPages}${attachment}</div>`;
}
function renderLetterHistory(){
  const rows=(company.letters||[]).slice().sort((a,b)=>String(b.created_at||"").localeCompare(String(a.created_at||""))).slice(0,30);
  if($("letterHistoryTable"))$("letterHistoryTable").innerHTML=rows.map(x=>`<tr><td>${esc(x.issue_date||"—")}</td><td>${esc(staffName(x.staff_id))}</td><td>${esc(letterTypeLabel(x.letter_type))}</td><td>${esc(x.letter_number||"—")}</td><td>${esc(x.subject||"—")}</td></tr>`).join("")||`<tr><td colspan="5">No letters saved yet.</td></tr>`;
}

function publicEmployeeUrl(code){return new URL(`employee.html?employee=${encodeURIComponent(code)}`,window.location.href).href}
function idCardHtml(s){let p=company.profile||{},code=s.employee_code||"",logo=p.logo_url||"logo.png",photo=s.photo_url||"",qrId=`qr-${String(s.id).replace(/[^a-z0-9]/gi,"")}`;return `<div class="id-sheet"><div class="id-card id-front"><div class="id-top"><img class="id-logo" src="${esc(logo)}" onerror="this.src='logo.png'"><div><div class="id-company">${esc(p.company_name||"SS ENTERPRISES")}</div><div class="id-tag">SS ENTERPRISES EMPLOYEE IDENTITY CARD</div></div></div><div class="id-main"><div>${photo?`<img class="id-photo" src="${esc(photo)}" alt="Employee photo">`:`<div class="id-photo id-photo-empty">PHOTO</div>`}</div><div class="id-info"><h3>${esc(s.full_name)}</h3><p><b>ID:</b> ${esc(code)}</p><p><b>Designation:</b> ${esc(s.designation||"Staff")}</p><p><b>Department:</b> ${esc(s.department||"—")}</p><p><b>Joining:</b> ${esc(s.joining_date||"—")}</p><span class="id-abha">${esc(s.department||s.designation||"SS Enterprises Project")}</span></div><div><div class="id-qr" id="${qrId}"></div><div class="id-project">Scan QR for employee + company details</div></div></div><div class="id-bottom"><div><small>${esc(p.address||"Donar Road, Darbhanga")}<br>Company: ${esc(p.phone||"")}<br>Mobile: ${esc(s.phone||"—")} · ${esc(code)}</small></div><div><small>Joining Date<br>${esc(s.joining_date||"—")}</small></div><div>${s.employee_signature_url?`<img class="id-sign" src="${esc(s.employee_signature_url)}">`:""}<small style="display:block;text-align:center">Employee Signature</small></div></div></div><div class="id-card id-back"><div class="id-top"><img class="id-logo" src="${esc(logo)}" onerror="this.src='logo.png'"><div><div class="id-company">TERMS &amp; AUTHORIZATION</div><div class="id-tag">${esc(p.company_name||"SS ENTERPRISES")}</div></div></div><div class="id-back-body"><h4>AUTHORITY STATEMENT</h4><div class="id-auth">Cardholder is authorised for the assigned ${esc(s.department||"company")} project and services. Property of ${esc(p.company_name||"SS Enterprises")}. Non-transferable.</div><h4>CONTACT INFORMATION</h4><div class="id-auth"><b>Office:</b> ${esc(p.address||"Donar Road, Darbhanga")}<br><b>Company Contact:</b> ${esc(p.phone||"")}<br><b>Employee Mobile:</b> ${esc(s.phone||"—")}</div><div class="id-back-sign"><div>${p.stamp_url?`<img class="id-stamp" src="${esc(p.stamp_url)}">`:""}<small>Company Stamp / Mohar</small></div><div>${p.signature_url?`<img class="id-authorized" src="${esc(p.signature_url)}">`:""}<small>Authorized Signatory</small></div><div><div class="id-qr id-qr-back" data-qr-url="${esc(publicEmployeeUrl(code))}"></div><small>SCAN FOR FULL ID + COMPANY DETAILS</small></div></div></div><div class="id-bottom"><small>${esc(p.company_name||"SS ENTERPRISES")} · ${esc(code)}</small><small>Joining Date: ${esc(s.joining_date||"—")}</small></div></div></div>`}
function renderIdCard(s,autoPrint=false){let box=$("idCardPreview");if(!box)return;box.hidden=false;box.innerHTML=`<div class="id-card-preview-label">Employee ID: ${esc(s.employee_code||"—")} · QR opens the employee and company profile</div>${idCardHtml(s)}<div class="id-actions"><button class="module-btn primary" id="printIdCard">Print ID Card</button><button class="module-btn ghost" id="closeIdCard">Close Preview</button></div>`;let qs=box.querySelectorAll(".id-qr");if(window.QRCode)qs.forEach(q=>{let text=q.dataset.qrUrl||publicEmployeeUrl(s.employee_code);new QRCode(q,{text,width:128,height:128,colorDark:"#061733",colorLight:"#ffffff",correctLevel:QRCode.CorrectLevel.M})});if(autoPrint)setTimeout(()=>printIdCard(s),350)}
function printIdCard(s){
  const source=document.createElement('div');
  source.style.cssText='position:fixed;left:-100000px;top:0;width:181mm;background:#fff;padding:0;margin:0;z-index:-1;';
  source.innerHTML=idCardHtml(s);
  document.body.appendChild(source);
  const cards=source.querySelectorAll('.id-card');
  const waitForImages=()=>Promise.all([...source.querySelectorAll('img')].map(img=>img.complete?Promise.resolve():new Promise(r=>{img.onload=r;img.onerror=r})));
  const makeQr=()=>{if(!window.QRCode)return;source.querySelectorAll('.id-qr').forEach(q=>{q.innerHTML='';new QRCode(q,{text:q.dataset.qrUrl||publicEmployeeUrl(s.employee_code),width:256,height:256,colorDark:'#061733',colorLight:'#ffffff',correctLevel:QRCode.CorrectLevel.M})})};
  const openPrint=(images)=>{
    const w=window.open('','_blank');
    if(!w){document.body.removeChild(source);return msg('Please allow pop-ups to print the ID Card.');}
    const pageCss=`@page{size:A4;margin:12mm}html,body{margin:0;padding:0;background:#fff!important}body{font-family:Arial,sans-serif} .id-pdf-sheet{display:flex;flex-direction:column;gap:8mm;align-items:center;width:100%}.id-pdf-card{display:block;width:85.6mm;height:54mm;object-fit:fill;break-inside:avoid;page-break-inside:avoid}`;
    w.document.open();
    w.document.write('<!doctype html><html><head><meta charset="utf-8"><title>SS Enterprises ID Card - '+esc(s.full_name)+'</title><style>'+pageCss+'</style></head><body><div class="id-pdf-sheet">'+images.map(src=>'<img class="id-pdf-card" src="'+src+'">').join('')+'</div></body></html>');
    w.document.close();
    setTimeout(()=>{w.focus();w.print();setTimeout(()=>w.close(),500);},500);
    document.body.removeChild(source);
  };
  const run=async()=>{
    makeQr();
    await waitForImages();
    if(!window.html2canvas){
      document.body.removeChild(source);
      const w=window.open('','_blank');
      if(!w)return;
      const css=`@page{size:A4;margin:12mm}html,body{margin:0;padding:0;background:#fff!important;-webkit-print-color-adjust:exact!important;print-color-adjust:exact!important}.id-sheet{display:grid;grid-template-columns:1fr 1fr;gap:7mm}.id-card{width:85.6mm;height:54mm;box-sizing:border-box;background:#061733!important;background-image:linear-gradient(135deg,#061733 0%,#0b2e5d 65%,#17457d 100%)!important;color:#fff;-webkit-print-color-adjust:exact!important;print-color-adjust:exact!important;overflow:hidden;position:relative}.id-top{display:flex;align-items:center;gap:2.5mm;padding:3.2mm 3.5mm 2.4mm;border-bottom:1px solid rgba(219,181,78,.55)}.id-logo{width:14mm;height:14mm;object-fit:contain;background:#fff;border-radius:2mm;padding:1mm}.id-company{font-size:4.3mm;font-weight:900}.id-tag{font-size:2.3mm;color:#d7e5f5}.id-main{display:grid;grid-template-columns:22mm 1fr 20mm;gap:2.4mm;padding:3.2mm}.id-photo{width:21mm;height:26mm;object-fit:cover;background:#eaf0f6;border:1px solid #d4b25a}.id-info h3{font-size:4.3mm;margin:0 0 1mm}.id-info p{font-size:2.45mm;margin:1mm 0}.id-info b,.id-back-body h4{color:#f0cf73}.id-qr{background:#fff;padding:1.3mm;width:18mm;height:18mm}.id-qr canvas,.id-qr img{width:100%!important;height:100%!important}.id-bottom{display:flex;justify-content:space-between;align-items:end;padding:1.7mm 3.5mm 2.5mm;border-top:1px solid rgba(255,255,255,.14);position:absolute;left:0;right:0;bottom:0}.id-sign{max-width:22mm;max-height:8mm;object-fit:contain;background:#fff}.id-back-body{padding:3.5mm}.id-auth{border:1px solid rgba(255,255,255,.12);padding:2.4mm;font-size:2.45mm;line-height:1.4;margin-bottom:3mm}.id-back-sign{display:grid;grid-template-columns:1fr 1fr 1fr;gap:2mm;align-items:end;margin-top:4mm;text-align:center;font-size:2mm}.id-back-sign img{display:block;margin:auto;max-width:17mm;max-height:9mm;object-fit:contain}.id-stamp,.id-authorized{background:#fff;max-width:17mm;max-height:9mm}`;
      w.document.write('<html><head><style>'+css+'</style></head><body>'+source.innerHTML+'<script src="https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js"><\\/script><script>setTimeout(function(){window.print()},1000)<\\/script></body></html>');w.document.close();return;
    }
    const images=[];
    for(const card of cards){
      const canvas=await window.html2canvas(card,{scale:3,useCORS:true,allowTaint:false,backgroundColor:null,logging:false,removeContainer:true});
      images.push(canvas.toDataURL('image/png'));
    }
    openPrint(images);
  };
  const lib=document.createElement('script');
  lib.src='https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js';
  lib.onload=run;lib.onerror=run;document.head.appendChild(lib);
}

function jobPosts(){return ["Field Executive","District Coordinator","Sales Executive","Data Entry Operator","Office Assistant","Other"]}
function renderJobApplications(){const tb=$("jobApplicationsTable");if(!tb)return;let rows=company.jobApplications||[];tb.innerHTML=rows.map(a=>`<tr><td><b>${esc(a.full_name||"")}</b><br><small>${esc(a.mobile||"")}</small></td><td>${esc(a.applied_post||"")}</td><td>${esc(a.qualification||"")}</td><td>${esc(a.experience||"")}</td><td>${esc(a.address||"")}</td><td>${esc(a.status||"new")}</td><td>${a.status==="selected"?'<span class="status-dot">Selected</span>':`<button class="module-btn ghost job-status" data-id="${a.id}" data-status="shortlisted">Shortlist</button> <button class="module-btn primary job-select" data-id="${a.id}">Select</button> <button class="module-btn danger job-status" data-id="${a.id}" data-status="rejected">Reject</button>`}</td></tr>`).join("")||'<tr><td colspan="7">No job applications yet.</td></tr>'}
async function selectJobApplicant(id){const a=(company.jobApplications||[]).find(x=>x.id===id);if(!a)return;if(a.status==="selected")return msg("Applicant already selected.");if(!confirm(`Select ${a.full_name} for ${a.applied_post}?`))return;let code=newEmployeeCode();let obj={employee_code:code,full_name:a.full_name||"",father_name:a.father_name||"",email:a.email||"",phone:a.mobile||"",designation:a.applied_post||"Field Executive",department:a.department||"",location:"Bihar",joining_date:null,photo_url:a.photo_url||"",employee_signature_url:"",salary:0,basic_salary:0,ta_travel:0,da_daily:0,rent_allowance:0,other_allowance:0,status:"active",bank_name:"",account_number:"",ifsc:"",address:a.address||"",notes:`Selected through Job Application on ${today()}`};if(!obj.full_name||!obj.phone)return msg("Applicant name and mobile are required.");let r=await sb.from("staff").insert(obj).select().single();if(r.error)return msg("Could not add selected applicant to Staff: "+r.error.message);let u=await sb.from("job_applications").update({status:"selected",selected_at:new Date().toISOString(),staff_id:r.data.id}).eq("id",id);if(u.error)return msg("Staff added, but application status update failed: "+u.error.message);await loadCompany();msg(`${a.full_name} selected and added to Staff as ${obj.designation} (${code}).`,true)}

function renderReports(){let active=company.staff.filter(s=>s.status==="active").length,present=company.attendance.filter(a=>a.attendance_date===today()&&a.status==="present").length,pm=company.payroll.filter(p=>(p.salary_month||"").slice(0,7)===monthNow()).reduce((a,x)=>a+Number(x.net_salary||0),0),inc=company.income.reduce((a,x)=>a+Number(x.amount||0),0),exp=company.expenses.reduce((a,x)=>a+Number(x.amount||0),0);$("reportStaff").textContent=active;$("reportPresent").textContent=present;$("reportPayroll").textContent=money(pm);$("reportNet").textContent=money(inc-exp);$("reportText").textContent=`Active staff: ${active}. Present today: ${present}. Current-month payroll: ${money(pm)}. Recorded income: ${money(inc)}. Recorded expenses: ${money(exp)}. Net recorded income/expense balance: ${money(inc-exp)}.`}

function renderCompanyProfile(){
  const p=company.profile||{};
  const set=(id,v)=>{if($(id))$(id).value=v??""};
  set("cp_name",p.company_name); set("cp_phone",p.phone); set("cp_email",p.email); set("cp_address",p.address);
  set("cp_offer_footer",p.offer_footer||"For SS Enterprises"); set("cp_joining_footer",p.joining_footer||"For SS Enterprises");
  set("cp_logo",p.logo_url); set("cp_signature",p.signature_url); set("cp_stamp",p.stamp_url);
  if($("companyLogoPreview"))$("companyLogoPreview").src=p.logo_url||"logo.png";
  if($("companySignaturePreview"))$("companySignaturePreview").src=p.signature_url||"";
  if($("companyStampPreview"))$("companyStampPreview").src=p.stamp_url||"";
  if($("companyProfileName"))$("companyProfileName").textContent=p.company_name||"SS ENTERPRISES";
}
async function uploadCompanyAsset(file,key){
  if(!file||!sb)return;
  let ext=(file.name.split(".").pop()||"png").toLowerCase().replace(/[^a-z0-9]/g,"")||"png";
  let path=`company/${key}-${Date.now()}-${Math.random().toString(36).slice(2)}.${ext}`;
  let r=await sb.storage.from("site-assets").upload(path,file,{upsert:false,contentType:file.type});
  if(r.error)return msg(r.error.message);
  company.profile[key]=sb.storage.from("site-assets").getPublicUrl(path).data.publicUrl;
  renderCompanyProfile();
  msg("Company asset uploaded. Press Save Company Profile.",true);
}
async function saveCompanyProfile(){
  let p=company.profile||{id:1};
  p.company_name=$("cp_name")?.value.trim()||"SS ENTERPRISES";
  p.phone=$("cp_phone")?.value.trim()||"";
  p.email=$("cp_email")?.value.trim()||"";
  p.address=$("cp_address")?.value.trim()||"Donar Road, Darbhanga";
  p.offer_footer=$("cp_offer_footer")?.value.trim()||"For SS Enterprises";
  p.joining_footer=$("cp_joining_footer")?.value.trim()||"For SS Enterprises";
  p.logo_url=$("cp_logo")?.value.trim()||"";
  p.signature_url=$("cp_signature")?.value.trim()||"";
  p.stamp_url=$("cp_stamp")?.value.trim()||"";
  let r=await sb.from("company_profile").upsert({id:1,company_name:p.company_name,address:p.address,phone:p.phone,email:p.email,logo_url:p.logo_url,signature_url:p.signature_url,stamp_url:p.stamp_url,offer_footer:p.offer_footer,joining_footer:p.joining_footer,updated_at:new Date().toISOString()});
  if(r.error)return msg("Company profile save failed: "+r.error.message);
  company.profile=p; renderCompanyProfile(); msg("Company Profile saved. Offer Letter and ID Card will use these assets.",true);
}

function renderCompanyDocuments(){
  const box=$("companyDocumentsList"); if(!box)return;
  const docs=Array.isArray(data.settings.companyDocuments)?data.settings.companyDocuments:[];
  box.innerHTML=docs.map((d,i)=>`<div class="company-doc-row"><div><b>${esc(d.name||"Company Document")}</b><small>${esc(d.fileName||"")}</small></div><div class="company-doc-actions">${d.url?`<a class="module-btn ghost" href="${d.url}" target="_blank" rel="noopener">View / Download</a>`:""}<button class="module-btn danger delete-company-doc" data-index="${i}">Delete</button></div></div>`).join("")||'<div class="company-note">अभी कोई company document upload नहीं है।</div>';
}
async function uploadCompanyDocument(file){
  if(!file||!sb)return;
  const ext=(file.name.split(".").pop()||"pdf").toLowerCase().replace(/[^a-z0-9]/g,"")||"pdf";
  const path=`company-documents/${Date.now()}-${Math.random().toString(36).slice(2)}.${ext}`;
  const r=await sb.storage.from("site-assets").upload(path,file,{upsert:false,contentType:file.type||"application/octet-stream"});
  if(r.error)return msg("Document upload failed: "+r.error.message);
  const url=sb.storage.from("site-assets").getPublicUrl(path).data.publicUrl;
  if(!Array.isArray(data.settings.companyDocuments))data.settings.companyDocuments=[];
  data.settings.companyDocuments.push({name:file.name.replace(/\.[^.]+$/,""),fileName:file.name,url,uploadedAt:new Date().toISOString()});
  renderCompanyDocuments(); await saveSite(); msg("Company document uploaded successfully.",true);
}

