async function blobToBase64(blob){return await new Promise((resolve,reject)=>{const fr=new FileReader();fr.onload=()=>resolve(String(fr.result||'').split(',')[1]||'');fr.onerror=()=>reject(fr.error||new Error('Could not read PDF.'));fr.readAsDataURL(blob)})}
async function urlToBase64(url){const r=await fetch(url,{cache:'no-store'});if(!r.ok)throw new Error('Terms & Conditions PDF could not be loaded.');return await blobToBase64(await r.blob())}
function lockLetterImageSize(img,maxW,maxH){
  const nw=Number(img.naturalWidth||img.width||1), nh=Number(img.naturalHeight||img.height||1);
  const scale=Math.min(maxW/nw,maxH/nh,1);
  const w=Math.max(1,Math.round(nw*scale)), h=Math.max(1,Math.round(nh*scale));
  img.style.width=w+'px'; img.style.height=h+'px';
  img.style.maxWidth=maxW+'px'; img.style.maxHeight=maxH+'px';
  img.style.objectFit='contain'; img.setAttribute('width',String(w)); img.setAttribute('height',String(h));
}
async function buildLetterPdfBase64(){
  if(!window.html2pdf)throw new Error('PDF engine is not loaded. Please refresh the Admin Panel and try again.');
  const full=document.createElement('div');full.innerHTML=letterHtml();
  const root=full.querySelector('.letter-document');if(!root)throw new Error('Letter preview is empty.');
  // The uploaded Terms & Conditions PDF is rendered as four exact visual pages
  // inside the Offer Letter PDF. This keeps the approved design intact.
  root.style.cssText='width:794px;background:#fff;margin:0;padding:0;color:#18283f;font-family:Georgia,"Times New Roman",serif;';
  const pages=[...root.querySelectorAll('.letter-page')];
  pages.forEach((el,i)=>{
    el.style.boxSizing='border-box';
    el.style.width='794px';
    el.style.height='1122px';
    el.style.minHeight='1122px';
    el.style.margin='0';
    el.style.padding='34px 42px';
    el.style.background='#fff';
    el.style.border='1px solid #cbd8e8';
    el.style.pageBreakAfter=i<pages.length-1?'always':'auto';
    el.style.breakAfter=i<pages.length-1?'page':'auto';
    el.style.breakInside='avoid';
    el.style.pageBreakInside='avoid';
    el.style.overflow='hidden';
  });
  root.querySelectorAll('.letter-page.salary-page').forEach(el=>{el.style.pageBreakBefore='always';el.style.breakBefore='page'});
  root.querySelectorAll('.tc-image-page').forEach(el=>{
    el.style.padding='0';
    el.style.height='1122px';
    el.style.minHeight='1122px';
    el.style.display='block';
    el.style.position='relative';
    el.style.overflow='hidden';
    el.style.background='#fff';
  });
  root.querySelectorAll('.tc-pdf-wrap').forEach(el=>{
    el.style.width='794px';
    el.style.height='1122px';
    el.style.display='flex';
    el.style.alignItems='center';
    el.style.justifyContent='center';
    el.style.overflow='hidden';
  });
  root.querySelectorAll('.tc-pdf-image').forEach(img=>{
    img.style.width='794px';
    img.style.height='1027px';
    img.style.maxWidth='794px';
    img.style.maxHeight='1027px';
    img.style.objectFit='fill';
    img.style.display='block';
  });
  root.querySelectorAll('.tc-dynamic-date').forEach(el=>{
    el.style.position='absolute';
    el.style.left='399px';
    el.style.top='722px';
    el.style.width='170px';
    el.style.height='28px';
    el.style.boxSizing='border-box';
    el.style.padding='3px 4px';
    el.style.background='#fff';
    el.style.color='#18283f';
    el.style.fontFamily='Arial,sans-serif';
    el.style.fontSize='11px';
    el.style.lineHeight='20px';
    el.style.textAlign='left';
    el.style.zIndex='5';
  });
  root.querySelectorAll('img').forEach(img=>{
    img.crossOrigin='anonymous';
    img.style.maxWidth='110px';
    img.style.maxHeight='55px';
    img.style.width='auto';
    img.style.height='auto';
    img.style.objectFit='contain';
  });
  root.querySelectorAll('.authorized-sign-img').forEach(img=>{img.style.maxWidth='110px';img.style.maxHeight='35px'});
  root.querySelectorAll('.stamp-img').forEach(img=>{img.style.maxWidth='75px';img.style.maxHeight='75px'});
  root.querySelectorAll('.employee-sign-img').forEach(img=>{img.style.maxWidth='100px';img.style.maxHeight='35px'});
  root.querySelectorAll('.tc-company-auth-box img').forEach(img=>{img.style.maxWidth='110px';img.style.maxHeight='40px'});
  root.querySelectorAll('.tc-company-auth-box .tc-company-stamp').forEach(img=>{img.style.maxWidth='75px';img.style.maxHeight='75px'});
  root.querySelectorAll('.tc-pdf-image').forEach(img=>{
    img.style.width='794px';img.style.height='1027px';img.style.maxWidth='794px';img.style.maxHeight='1027px';img.style.objectFit='fill';
  });
  const holder=document.createElement('div');holder.style.cssText='position:fixed;left:-10000px;top:0;width:794px;background:#fff;z-index:-1;';holder.appendChild(root);document.body.appendChild(holder);
  try{
    const imgs=[...root.querySelectorAll('img')];
    await Promise.all(imgs.map(img=>img.complete?Promise.resolve():new Promise(r=>{img.onload=r;img.onerror=r})));
    root.querySelectorAll('.authorized-sign-img').forEach(img=>lockLetterImageSize(img,110,35));
    root.querySelectorAll('.stamp-img').forEach(img=>lockLetterImageSize(img,75,75));
    root.querySelectorAll('.employee-sign-img').forEach(img=>lockLetterImageSize(img,100,35));
    root.querySelectorAll('.tc-company-signature').forEach(img=>lockLetterImageSize(img,110,35));
    root.querySelectorAll('.tc-company-stamp').forEach(img=>lockLetterImageSize(img,75,75));
    const pdfBlob=await html2pdf().set({margin:[0,0,0,0],filename:'SS-Enterprises-Letter.pdf',image:{type:'jpeg',quality:0.97},html2canvas:{scale:1.6,useCORS:true,backgroundColor:'#ffffff',logging:false},jsPDF:{unit:'mm',format:'a4',orientation:'portrait'},pagebreak:{mode:['css']}}).from(root).outputPdf('blob');
    return await blobToBase64(pdfBlob);
  }finally{holder.remove()}
}
async function emailCurrentLetter(){
  const s=selectedLetterStaff();
  if(!s?.email)return msg('Staff email is not available. Please add the employee email in Staff Management.');
  const h=letterHtml();
  if(!h)return msg('Generate the letter first.');
  if($('letterPreview'))$('letterPreview').innerHTML=h;

  const type=$('letterType').value;
  const subject=$('letterSubject').value||'SS Enterprises Letter';
  const button=$('emailLetter');
  const oldText=button?.textContent||'Email Letter + T&C';

  if(button){button.disabled=true;button.textContent='Preparing PDF…'}

  try{
    const letterContent=await buildLetterPdfBase64();
    const attachments=[{
      filename:`SS-Enterprises-${String(s.employee_code||s.id||'Employee')}-${type==='offer'?'Offer-Letter':type==='joining'?'Joining-Letter':'Letter'}.pdf`,
      content:letterContent,
      content_type:'application/pdf'
    }];

    // The generated Offer PDF already contains the approved four-page Terms & Conditions.
    // Do not attach an older external template as a second, conflicting T&C document.
    let termsContent='';

    if(button)button.textContent='Sending…';
    if(!sb)throw new Error('Supabase is not connected.');

    const sessionResult=await sb.auth.getSession();
    const accessToken=sessionResult?.data?.session?.access_token;
    if(!accessToken)throw new Error('Admin session has expired. Please log in again.');

    const supabaseUrl=window.SS_CONFIG?.SUPABASE_URL;
    const anonKey=window.SS_CONFIG?.SUPABASE_ANON_KEY;
    if(!supabaseUrl||!anonKey)throw new Error('Supabase configuration is missing.');

    const endpoint=`${supabaseUrl.replace(/\/$/,'')}/functions/v1/send-letter-email`;
    const payload={
      to:s.email.trim(),
      subject,
      employeeName:s.full_name||'Employee',
      employeeCode:s.employee_code||'',
      letterType:type,
      attachments,
      termsContent
    };

    let response=null;
    let lastError=null;

    // One controlled retry helps with a cold-start/transient 502/503/504.
    for(let attempt=1;attempt<=2;attempt++){
      const controller=new AbortController();
      const timer=setTimeout(()=>controller.abort(),45000);
      try{
        response=await fetch(endpoint,{
          method:'POST',
          headers:{
            Authorization:`Bearer ${accessToken}`,
            apikey:anonKey,
            'Content-Type':'application/json'
          },
          body:JSON.stringify(payload),
          signal:controller.signal,
          cache:'no-store'
        });
        if(response.ok||!([502,503,504].includes(response.status))||attempt===2)break;
        await new Promise(r=>setTimeout(r,1200));
      }catch(err){
        lastError=err;
        if(attempt===2)break;
        await new Promise(r=>setTimeout(r,1200));
      }finally{
        clearTimeout(timer);
      }
    }

    if(!response){
      if(lastError?.name==='AbortError')throw new Error('Email service timed out. Please try again.');
      throw new Error(lastError?.message||'Could not connect to the email service.');
    }

    let result={};
    try{result=await response.json()}catch(_){result={}}

    if(!response.ok){
      throw new Error(result?.error||result?.message||`Email service returned HTTP ${response.status}.`);
    }

    msg(`Letter sent successfully to ${s.email}${type==='offer'?' with the original 5-page Terms & Conditions PDF.':'.'}`,true);
  }catch(err){
    console.error('EMAIL LETTER ERROR:',err);
    msg('Email failed: '+(err?.message||err));
  }finally{
    if(button){button.disabled=false;button.textContent=oldText}
  }
}

