let printCss=`@page{size:A4;margin:10mm}html,body{margin:0;padding:0;background:#fff!important}body{font-family:Georgia,'Times New Roman',serif;color:#18283f}.letter-document{max-width:none;margin:0}.letter-page{position:relative;overflow:hidden;background:#fff;border:1px solid #cbd8e8;padding:35px 42px;box-sizing:border-box;min-height:277mm;margin:0;line-height:1.55;font-size:11.5px;page-break-after:always}.letter-watermark{position:absolute;top:36%;left:8%;font-family:Arial,sans-serif;font-size:70px;font-weight:800;letter-spacing:5px;color:rgba(6,23,51,.055);transform:rotate(-28deg)}.letter-page>*{position:relative;z-index:1}.letter-head{display:flex;align-items:center;gap:12px;padding-bottom:9px;border-bottom:3px solid #c99b2e}.letter-head img{width:64px;height:64px;object-fit:contain}.letter-head h2{font-family:Arial,sans-serif;color:#08234a;letter-spacing:1px;margin:0}.letter-meta{display:flex;justify-content:space-between;margin:12px 0;font:11px Arial,sans-serif}.letter-to{background:#eef4fa;border-left:4px solid #c99b2e;padding:8px 11px;font:11px Arial,sans-serif}.letter-subject{color:#08234a;text-align:center;text-decoration:underline;text-underline-offset:5px}.letter-detail-box{background:#f4f7fb;border:1px solid #d6deea;border-radius:8px;padding:10px 14px;margin:12px 0;font:11px Arial,sans-serif}.letter-detail-box p{margin:5px 0}.letter-note{background:#fff7df;border-left:4px solid #d3a52f;padding:8px 10px}.letter-sign{display:grid;grid-template-columns:1fr 1fr 1fr;gap:16px;margin-top:20px}.letter-sign img{max-width:150px;max-height:55px;width:auto;height:auto;object-fit:contain}.letter-sign .authorized-sign-img{max-width:150px;max-height:45px;width:auto;height:auto}.letter-sign .stamp-img{max-width:130px;max-height:130px;width:auto;height:auto}.letter-sign .employee-sign-img{max-width:120px;max-height:43px;width:auto;height:auto}.tc-company-auth-box img{max-width:150px;max-height:55px;width:auto;height:auto;object-fit:contain}.tc-company-auth-box .tc-company-stamp{max-width:130px;max-height:130px;width:auto;height:auto}.letter-footer{margin-top:12px;padding-top:9px;border-top:1px solid #cfd8e5;text-align:center;font:10px Arial,sans-serif;color:#607086}.salary-breakup-final{width:100%;border-collapse:collapse;margin:18px 0;font:11px Arial,sans-serif}.salary-breakup-final th,.salary-breakup-final td{padding:8px;border:1px solid #d6deea}.salary-breakup-final th{background:#09264f;color:#fff;text-align:left}.salary-breakup-final th:nth-child(n+2),.salary-breakup-final td:nth-child(n+2){text-align:right}.salary-breakup-final .salary-total th{background:#09264f;color:#fff}.annual-summary{font:11px Arial,sans-serif;color:#17385e}.two-sign{grid-template-columns:1fr 1fr}.salary-page{page-break-before:auto}`;w.document.write(`<html><head><meta charset="utf-8"><title>SS Enterprises Letter</title><link rel="stylesheet" href="${new URL("styles.css",window.location.href).href}"><style>${printCss}</style></head><body>${h}</body></html>`);
